export function coursePhotoKindFromTitle(title) {
  const text = String(title || '')
  if (/Extension\b/i.test(text)) return 'extension'
  if (/Mini\s*Test\b/i.test(text)) return 'mini-test'
  const lesson = text.match(/Lesson\s+(\d+)/i)
  if (lesson) return `lesson-${lesson[1]}`
  if (/TOEIC có thật sự khó/i.test(text)) return 'lesson-1'
  if (/Tìm hiểu TOEIC/i.test(text)) return 'lesson-2'
  if (/Hướng dẫn học tập/i.test(text)) return 'lesson-3'
  const kind = text.match(/Bài\s+(\d+)/i)
  if (kind) return `lesson-${kind[1]}`
  return 'lesson-1'
}

export function getCoursePhotos(unit, kind) {
  const unitMap = TCO_COURSE_PHOTOS[Number(unit)] || {}
  if (kind && unitMap[kind]?.length) return unitMap[kind]
  return []
}

export function getLessonCoursePhotos(lesson, limit = 4) {
  const title = lesson?.title || ''
  const unitMatch = String(title).match(/Unit\s*0?(\d+)/i)
  const unit = unitMatch ? Number(unitMatch[1]) : null
  if (!unit) return []
  return getCoursePhotos(unit, coursePhotoKindFromTitle(title)).slice(0, limit)
}
